customMethods.script:
# Get the index of the toast from the instances if exists else None
_index = None
for index, toast in enumerate(self.props.instances):
	if toast['toastID'] == toastID:
		_index = index
		break;
return _index

# Removes the specific toast from the instances by index
try:
	del self.props.instances[index]
except:
	system.perspective.print('Toast Handler could not clear toast, index ({}) does not exist.'.format(index))

messageHandlers.script:
screenID = payload.get('screenID',None)
if screenID == None or screenID == self.custom.screenID:
	# Add payload (Message view params) to the flex repeater instance and set props.style zIndex
	self.props.style.zIndex = 1
	toast = self.configureToast(payload)
	try:
		errorMessage = payload["content"].split("<br>")
		self.setViewPath("Library/Toast/Message/Basic")
		if len(errorMessage) <= 1 and len(errorMessage[0]) <= 45:
		    toast["message"] = payload["content"]
		    toast["content"] = None
		else:
		    self.setViewPath("Library/Toast/Message/Expanding")
	except:
		pass
	self.props.instances.append(toast)
